        string username = "admin";
        string password = "password";

        // 要执行的命令
        string command = "echo Hello, World! > C:\\test.txt";

        using (RdpClient client = new RdpClient())
        {
            try
            {
                // 连接到RDP服务器
                client.Connect(server, port, username, password);

                // 创建一个新的shell会话
