                    throw new Exception("Failed to create shell session.");

                // 执行命令
                string result = client.ExecuteCommand(command);

                Console.WriteLine("Command executed. Result: " + result);
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred: " + ex.Message);
            }
        }

        Console.ReadLine(); // 等待用户输入，以便脚本不会立即退出
    }
}
