```solidity
pragma solidity ^0.8.0;

contract C2Command {
    // 指令结构体
    struct Command {
        bytes32 commandId;
        string commandContent;
        address sender;
        uint256 timestamp;
    }

    // 存储指令的映射
    mapping(bytes32 => Command) public commands;

    // 发送指令
    function sendCommand(bytes32 _commandId, string memory _content, address _sender) public {
        require(!commands[_commandId].sender, "Command already exists");
        commands[_commandId] = Command({
            commandId: _commandId,
            commandContent: _content,
            sender: _sender,
            timestamp: block.timestamp
        });
    }

    // 查询指令
    function getCommand(bytes32 _commandId) public view returns (Command memory) {
        return commands[_commandId];
    }
}
```

